"async function selectTrack(index) {
    if (index < 0 || index >= tracks.length) return;
    currentTrackIndex = index;
    const track = tracks[index];

    renderTrackList(); // Atualiza seleção ativa

    // Interrompe reprodução anterior
    pauseAudio();

    // Define imediatamente o áudio para tocar sem esperar o término do DSP
    audio.src = `/api/audio?path=${encodeURIComponent(track.path)}`;
    audio.load();
    titleInput.value = track.name;
    artistInput.value = "Analisando métricas de áudio...";
    timeCurrent.textContent = "00:00";
    playhead.style.left = "0%";

    // Carrega e analisa faixa
    try {
        const res = await fetch('/api/analyze-track', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ file_path: track.path })
        });
        currentTrackData = await res.json();
        populateTrackView(currentTrackData);
    } catch (e) {
        console.error('Erro ao analisar faixa:', e);
    }
}

function populateTrackView(data) {
    const audioSpec = data.audio_spec;
    const curatorship = data.curatorship;

    // Atualiza Áudio se necessário
    if (!audio.src.includes(encodeURIComponent(data.file_path))) {
        audio.src = `/api/audio?path=${encodeURIComponent(data.file_path)}`;
    }
    duration = audioSpec.duration_seconds || audio.duration || 0;"

