"function playAudio() {
    if (!audio.src) {
        if (tracks.length > 0 && currentTrackIndex >= 0) {
            audio.src = `/api/audio?path=${encodeURIComponent(tracks[currentTrackIndex].path)}`;
        } else {
            return;
        }
    }
    audio.play().then(() => {
        isPlaying = true;
        playIcon.className = "fa-solid fa-pause";
    }).catch(err => {
        console.error("Erro ao reproduzir áudio:", err);
        if (err.name !== "AbortError") {
            alert("Não foi possível reproduzir o áudio no navegador: " + err.message);
        }
        pauseAudio();
    });
}

function pauseAudio() {
    audio.pause();
    isPlaying = false;
    playIcon.className = "fa-solid fa-play";
    if (simTimeout) {
        clearTimeout(simTimeout);
        simTimeout = null;
    }
}

audio.addEventListener('loadedmetadata', () => {
    if (!duration || duration <= 0) {
        duration = audio.duration || 0;
        timeTotal.textContent = formatTime(duration);
    }
});

audio.addEventListener('error', (e) => {
    console.error('Audio element error:', audio.error);
    const code = audio.error ? audio.error.code : 'Desconhecido';
    alert(`Erro ao carregar o arquivo de áudio (Código ${code}). Verifique se o formato é suportado pelo navegador.`);
    pauseAudio();
});

audio.addEventListener('timeupdate', () => {
    updatePlayhead();
});

function updatePlayhead() {
    const curDuration = duration || audio.duration || 1;
    const pct = (audio.currentTime / curDuration) * 100;
    playhead.style.left = `${Math.min(100, Math.max(0, pct))}%`;
    timeCurrent.textContent = formatTime(audio.currentTime);
}

audio.addEventListener('ended', () => {
    pauseAudio();
});

volumeSlider.addEventListener('input', () => {
    audio.volume = parseFloat(volumeSlider.value);
});"

