"import os
from typing import Tuple
from studio.core.taxonomy import VocalProfile
from studio.core.music_classifier import MusicClassifier

class VocalAnalyzer:
    def __init__(self):
        self.classifier = MusicClassifier()

    def classify_vocal_profile(self, file_path: str, title: str = "", artist: str = "") -> Tuple[VocalProfile, float]:
        """
        Classifica o perfil vocal de uma faixa musical.
        Retorna (VocalProfile, confidence_score).
        """
        try:
            import librosa
            y, sr = librosa.load(file_path, sr=22050, duration=30.0, mono=True)
            return self.classifier.classify_vocal_profile(y, sr, title or os.path.basename(file_path), artist)
        except Exception:
            return VocalProfile.INSTRUMENTAL, 0.70"

