429:     // Une os subgêneros do mapa padrão com quaisquer outros que a música já tenha
430:     const allSet = new Set([...available, ...selectedSubgenres, ...Object.keys(confidences)]);
431:     
432:     // Ordena priorizando quem tem maior confiança estimada pela IA
433:     const sortedTags = Array.from(allSet).sort((a, b) => {
434:         const confA = confidences[a] !== undefined ? confidences[a] : (selectedSubgenres.includes(a) ? 0.5 : 0.0);
435:         const confB = confidences[b] !== undefined ? confidences[b] : (selectedSubgenres.includes(b) ? 0.5 : 0.0);
436:         return confB - confA;
437:     });
