"@app.get("/api/browse-directories")
async def browse_directories(path: str = ""):
    """Permite navegação e exploração de pastas locais para seleção visual de catálogo."""
    current_path = os.path.abspath(path) if path else os.getcwd()
    if not os.path.exists(current_path) or not os.path.isdir(current_path):
        current_path = os.getcwd()

    parent = os.path.dirname(current_path) if current_path != "/" else "/"

    subdirs = []
    try:
        for item in sorted(os.listdir(current_path)):
            full_item = os.path.join(current_path, item)
            if os.path.isdir(full_item) and not item.startswith("."):
                subdirs.append({
                    "name": item,
                    "path": full_item
                })
    except PermissionError:
        pass

    return {
        "current_path": current_path,
        "parent_path": parent,
        "directories": subdirs
    }"

