btnProcessMp3.onclick = async () => {
    if (!currentTrackData) return;
    let outputDir = folderInput.value.trim();
    if (outputDir.includes('audio_in')) {
        outputDir = outputDir.replace('audio_in', 'audio_out');
    } else {
        const folderBase = outputDir.split(/[/\\]/).filter(Boolean).pop() || 'tratadas';
        outputDir = (configData && configData.default_treated_dir)
            ? `${configData.default_treated_dir}/${folderBase}`
            : `audio_out/${folderBase}`;
    }
    btnProcessMp3.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Processando...';
    try {
        const res = await fetch('/api/process-track', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ file_path: currentTrackData.file_path, output_dir: outputDir })
        });
        const data = await res.json();
        if (data.success) {
            alert(`✓ Faixa normalizada com sucesso a -14 LUFS em:\n${data.output_path}`);
        }
    } catch (e) {
        alert(`Erro ao processar: ${e.message}`);
    } finally {
        btnProcessMp3.innerHTML = '<i class="fa-solid fa-sliders"></i> Exportar MP3 Tratado';
    }
};"

