"// 3. SELEÇÃO & NAVEGAÇÃO DE DIRETÓRIOS
// ==========================================================================
async function scanFolder(folder) {
    if (!folder) return;
    folderInput.value = folder;
    trackListContainer.innerHTML = '<div class="empty-state"><i class="fa-solid fa-spinner fa-spin"></i><p>Escaneando pasta e lendo metadados de áudio...</p></div>';
    try {
        const res = await fetch(`/api/scan?folder=${encodeURIComponent(folder)}`);
        const data = await res.json();
        tracks = data.files || [];
        updateStats();
        updateBatchAnalyzeBanner();
        renderTrackList();
        if (tracks.length > 0) {
            selectTrack(0);
        } else {
            trackListContainer.innerHTML = '<div class="empty-state"><i class="fa-solid fa-folder-open"></i><p>Nenhuma música encontrada nesta pasta.<br>Verifique o caminho e tente novamente.</p></div>';
        }
    } catch (e) {
        trackListContainer.innerHTML = `<div class="empty-state"><i class="fa-solid fa-triangle-exclamation"></i><p>Erro ao escanear pasta: ${e.message}</p></div>`;
    }
}

function updateBatchAnalyzeBanner() {
    if (!batchAnalyzeBar) return;
    const pendingDsp = tracks.filter(t => !t.is_analyzed).length;
    if (pendingDsp > 0) {
        batchAnalyzeBar.style.display = 'block';
        if (batchAnalyzeMsg) {
            batchAnalyzeMsg.innerHTML = `<b>${pendingDsp}</b> ${pendingDsp === 1 ? 'faixa pendente' : 'faixas pendentes'} de análise DSP`;
        }
        if (batchAnalyzeRow) batchAnalyzeRow.style.display = 'flex';
        if (batchAnalyzeProgressBox) batchAnalyzeProgressBox.style.display = 'none';
    } else {
        batchAnalyzeBar.style.display = 'none';
    }
}

function updateStats() {
    statTotal.textContent = tracks.length;
    statApproved.textContent = tracks.filter(t => t.approval_status === 'Aprovado').length;
    statPending.textContent = tracks.filter(t => t.approval_status === 'Pendente').length;

