+let isBatchAnalyzingFolder = false;
+
+function setupBatchAnalyzeFolder() {
+    if (!btnStartBatchAnalyze || !btnCancelBatchAnalyze) return;
+
+    btnStartBatchAnalyze.onclick = async () => {
+        const pendingTracks = tracks.filter(t => !t.is_analyzed);
+        if (pendingTracks.length === 0) {
+            alert("Todas as faixas desta pasta já foram analisadas!");
+            return;
+        }
+
+        isBatchAnalyzingFolder = true;
+        batchAnalyzeRow.style.display = 'none';
+        batchAnalyzeProgressBox.style.display = 'flex';
+
+        const total = pendingTracks.length;
+        let processed = 0;
+
+        for (let i = 0; i < pendingTracks.length; i++) {
+            if (!isBatchAnalyzingFolder) break;
+
+            const t = pendingTracks[i];
+            const pct = Math.round((i / total) * 100);
+
+            if (batchProgressTitle) batchProgressTitle.textContent = `[${i + 1}/${total}] ${t.title || t.name}`;
+            if (batchProgressPct) batchProgressPct.textContent = `${pct}%`;
+            if (batchProgressIndicator) batchProgressIndicator.style.width = `${pct}%`;
+
+            try {
+                const res = await fetch('/api/analyze-track', {
+                    method: 'POST',
+                    headers: { 'Content-Type': 'application/json' },
