"const aiTopSubgenresList = document.getElementById('ai-top-subgenres-list');

// DOM Elements - Inteligência de Mercado & Hit Rating
const cardMarketIntel = document.getElementById('card-market-intel');
const inpReleaseYear = document.getElementById('inp-release-year');
const inpPeakYear = document.getElementById('inp-peak-year');
const badgeDecade = document.getElementById('badge-decade');
const hitStarsDisplay = document.getElementById('hit-stars-display');
const hitRatingText = document.getElementById('hit-rating-text');
const hitScoreButtons = document.querySelectorAll('.btn-hit-score');
const chartNotesText = document.getElementById('chart-notes-text');

const HIT_DESCRIPTIONS = {
    1: "Catálogo / B-Side",
    2: "Álbum Conhecido",
    3: "Top 40 / Rádio",
    4: "Grande Hit (Top 10)",
    5: "Mega Hit Mundial (#1)"
};

let currentHitScore = 1;

function getDecadeLabel(year) {
    if (!year || isNaN(year)) return "Desconhecido";
    const y = parseInt(year);
    if (y < 1920 || y > 2035) return "Desconhecido";
    const dec = Math.floor(y / 10) * 10;
    if (dec >= 1930 && dec <= 1990) {
        return `Anos ${String(dec).slice(-2)}`;
    }
    return `Anos ${dec}`;
}

function setHitScoreUI(score) {
    currentHitScore = parseInt(score) || 1;
    if (currentHitScore < 1) currentHitScore = 1;
    if (currentHitScore > 5) currentHitScore = 5;

    if (hitStarsDisplay) {
        hitStarsDisplay.textContent = '⭐'.repeat(currentHitScore);
    }
    if (hitRatingText) {
        hitRatingText.textContent = HIT_DESCRIPTIONS[currentHitScore] || `Score ${currentHitScore}`;
    }
    if (hitScoreButtons) {
        hitScoreButtons.forEach(btn => {
            if (parseInt(btn.dataset.score) === currentHitScore) {
                btn.classList.add('active');
            } else {
                btn.classList.remove('active');
            }
        });
    }
}
"

