"// Botão Aprovar e Próxima (Promoção sem re-encoding)
btnApprove.onclick = async () => {
    if (!currentTrackData) return;

    // 1. Salva dados curados
    await saveTrackData(false, 'Aprovado');

    // 2. Promove diretamente o arquivo tratado para audio_out sem re-encoding DSP
    try {
        let targetOut = (configData && configData.default_treated_dir) ? configData.default_treated_dir : 'audio_out';
        const res = await fetch('/api/approve-track', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                file_path: currentTrackData.file_path,
                target_out_dir: targetOut,
                curator_notes: curatorNotes ? curatorNotes.value.trim() : ""
            })
        });
        const data = await res.json();
        if (data.success && data.track) {
            currentTrackData.treated_file_path = data.track.treated_file_path;
            currentTrackData.curatorship.approval_status = 'Aprovado';
            if (currentTrackIndex >= 0 && tracks[currentTrackIndex]) {
                tracks[currentTrackIndex].approval_status = 'Aprovado';
                tracks[currentTrackIndex].treated_file_path = data.track.treated_file_path;
            }
            updateStats();
