"async function loadInitialConfig() {
    try {
        const res = await fetch('/api/config');
        configData = await res.json();
        if (configData.default_raw_dir) {
            folderInput.value = configData.default_raw_dir;
            scanFolder(configData.default_raw_dir);
        }
        // Inicializa Pasta de Destino das Mídias (audio_out / servidor)
        if (outputFolderInput) {
            const savedOut = localStorage.getItem('imc_studio_output_folder');
            outputFolderInput.value = savedOut || configData.default_treated_dir || 'audio_out';
            outputFolderInput.addEventListener('change', () => {
                localStorage.setItem('imc_studio_output_folder', outputFolderInput.value.trim());
            });
        }
        if (outputPresets) {
            outputPresets.forEach(btn => {
                btn.onclick = () => {
                    const out = btn.dataset.outFolder;
                    if (outputFolderInput) {
                        outputFolderInput.value = out;
                        localStorage.setItem('imc_studio_output_folder', out);
                    }
                };
            });
        }
    } catch (e) {
        console.error('Falha ao carregar configurações iniciais:', e);
    }
}"

