"@app.post("/api/approve-track")
async def approve_track(req: ApproveTrackRequest):
    file_path = req.file_path
    target_out = req.target_out_dir or os.path.join(os.getcwd(), "audio_out")
    if target_out:
        try:
            db.set_setting("last_output_folder", os.path.abspath(target_out))
        except Exception:
            pass

    updated_track = db.promote_to_approved(file_path, target_out)
    if not updated_track:
        entry = metadata_cache.get(file_path)
        if not entry:
            raise HTTPException(status_code=404, detail="Faixa não encontrada")
        db.upsert_track(entry)
        updated_track = db.promote_to_approved(file_path, target_out)

    if req.curator_notes is not None and updated_track:
        updated_track.setdefault("curatorship", {})["curator_notes"] = req.curator_notes
        db.upsert_track(updated_track)

    if updated_track:
        metadata_cache[file_path] = updated_track
        save_cache()

    return {
        "success": True,
        "approval_status": "Aprovado",
        "track": updated_track,
        "db_stats": db.get_stats()
    }

@app.post("/api/update-settings")
async def update_settings(req: UpdateSettingsRequest):
    if req.input_folder:
        db.set_setting("last_input_folder", os.path.abspath(req.input_folder))
    if req.output_folder:
        db.set_setting("last_output_folder", os.path.abspath(req.output_folder))
    return {
        "success": True,
        "last_input_folder": db.get_setting("last_input_folder"),
        "last_output_folder": db.get_setting("last_output_folder")
    }"

