"def _run_native_picker(initial_dir: str = "", title: str = "Selecione uma Pasta") -> Dict[str, Any]:
    """Abre a janela de diálogo nativa do sistema operacional (Zenity no Linux / GNOME)."""
    init_path = initial_dir if (initial_dir and os.path.isdir(initial_dir)) else os.getcwd()
    zenity_bin = shutil.which("zenity")
    if zenity_bin:
        cmd = [
            zenity_bin,
            "--file-selection",
            "--directory",
            f"--title={title}",
            f"--filename={os.path.abspath(init_path)}/"
        ]
        try:
            res = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, timeout=300)
            if res.returncode == 0:
                selected = res.stdout.strip()
                if selected and os.path.isdir(selected):
                    audio_extensions = (".mp3", ".wav", ".flac", ".ogg", ".m4a")
                    try:
                        audio_count = sum(1 for f in os.listdir(selected) if f.lower().endswith(audio_extensions))
                    except Exception:
                        audio_count = 0
                    return {"success": True, "path": selected, "audio_count": audio_count}
            elif res.returncode == 1:
                return {"success": False, "cancelled": True}
        except subprocess.TimeoutExpired:
            return {"success": False, "error": "Tempo limite esgotado"}
        except Exception as e:
            return {"success": False, "error": str(e)}

    return {"success": False, "error": "Seletor nativo Zenity não disponível no sistema"}

