"// Funções e Botões de Decisão do Curador (Painel Esquerdo & Painel de Ações)
async function approveTrack() {
    if (!currentTrackData) return;

    // 1. Salva dados curados
    await saveTrackData(false, 'Aprovado');

    // 2. Promove diretamente o arquivo tratado para o diretório de destino selecionado sem re-encoding DSP
    try {
        let targetOut = (outputFolderInput && outputFolderInput.value.trim()) 
            ? outputFolderInput.value.trim() 
            : ((configData && configData.default_treated_dir) ? configData.default_treated_dir : 'audio_out');
        const res = await fetch('/api/approve-track', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                file_path: currentTrackData.file_path,
                target_out_dir: targetOut,
                curator_notes: curatorNotes ? curatorNotes.value.trim() : ""
            })
        });
        const data = await res.json();
        if (!res.ok) {
            alert(`⚠️ Atenção: Não foi possível aprovar a faixa:\n\n${data.detail || "Erro ao aprovar faixa"}`);
            return;
        }
        if (data.success && data.track) {
            currentTrackData.treated_file_path = data.track.treated_file_path;
            currentTrackData.curatorship.approval_status = 'Aprovado';
            if (currentTrackIndex >= 0 && tracks[currentTrackIndex]) {
                tracks[currentTrackIndex].approval_status = 'Aprovado';
                tracks[currentTrackIndex].treated_file_path = data.track.treated_file_path;
            }
            updateStats();
            renderTrackList();
        }
    } catch (err) {
        console.error('Erro na promoção de aprovação:', err);
        alert(`Erro de comunicação com o servidor: ${err.message}`);
        return;
    }

    if (currentTrackIndex + 1 < tracks.length) {
        selectTrack(currentTrackIndex + 1);
    }
}

