        if cue_in >= 1.5:
            intro_boundary = int(loaded_sr * (cue_in - 0.5))
            intro_samples = y[:intro_boundary]
            if len(intro_samples) > 0:
                intro_rms = float(np.sqrt(np.mean(intro_samples**2)))
                intro_db = 20 * np.log10(intro_rms + 1e-9)
                if intro_db > -35.0:
