"function updateStats() {
    statTotal.textContent = tracks.length;
    statApproved.textContent = tracks.filter(t => t.approval_status === 'Aprovado').length;
    if (statInAnalysis) statInAnalysis.textContent = tracks.filter(t => t.approval_status === 'Em Análise').length;
    statPending.textContent = tracks.filter(t => t.approval_status === 'Pendente').length;
    statInapt.textContent = tracks.filter(t => t.approval_status === 'Rejeitado' || (t.ambience_fitness === 'Inapto' && t.approval_status !== 'Aprovado')).length;
}

function renderTrackList() {
    const query = searchInput.value.toLowerCase();
    const activeFilter = document.querySelector('.filter-pill.active')?.dataset.filter || 'all';

    const filtered = tracks.filter((t) => {
        const title = (t.title || t.name).toLowerCase();
        const artist = (t.artist || '').toLowerCase();
        const matchesQuery = title.includes(query) || artist.includes(query) || (t.rel_path && t.rel_path.toLowerCase().includes(query));
        if (!matchesQuery) return false;
        if (activeFilter === 'pending') return !t.is_analyzed || t.approval_status === 'Pendente';
        if (activeFilter === 'in_analysis') return t.approval_status === 'Em Análise';
        if (activeFilter === 'approved') return t.approval_status === 'Aprovado';
        if (activeFilter === 'inapt' || activeFilter === 'rejected') return t.approval_status === 'Rejeitado' || (t.ambience_fitness === 'Inapto' && t.approval_status !== 'Aprovado');
        return true;
    });"

