// DOM Elements - Toast Flutuante de Processamento de Aprovação
const approvalToast = document.getElementById('approval-toast');
const approvalToastIcon = document.getElementById('approval-toast-icon');
const approvalToastTitle = document.getElementById('approval-toast-title');
const approvalToastDesc = document.getElementById('approval-toast-desc');
let approvalToastTimer = null;

function showApprovalToast(type, title, desc) {
    if (!approvalToast) return;
    if (approvalToastTimer) clearTimeout(approvalToastTimer);

    approvalToast.className = 'approval-toast';
    if (type === 'success') {
        approvalToast.classList.add('toast-success');
        if (approvalToastIcon) approvalToastIcon.innerHTML = '<i class="fa-solid fa-circle-check"></i>';
    } else if (type === 'error') {
        approvalToast.classList.add('toast-error');
        if (approvalToastIcon) approvalToastIcon.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i>';
    } else {
        if (approvalToastIcon) approvalToastIcon.innerHTML = '<i class="fa-solid fa-circle-notch fa-spin"></i>';
    }

    if (approvalToastTitle) approvalToastTitle.textContent = title;
    if (approvalToastDesc) approvalToastDesc.textContent = desc;

    approvalToast.style.display = 'flex';
}

function hideApprovalToast(delayMs = 0) {
    if (!approvalToast) return;
    if (approvalToastTimer) clearTimeout(approvalToastTimer);
    if (delayMs > 0) {
        approvalToastTimer = setTimeout(() => {
            approvalToast.style.display = 'none';
        }, delayMs);
    } else {
        approvalToast.style.display = 'none';
    }
}

