/* ==========================================================================
   BOTÃO DE REANÁLISE RÁPIDA DE BLOCO (HEADER DE CADA CARD)
   ========================================================================== */
.btn-card-reanalyze {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: var(--text-secondary);
    padding: 3px 9px;
    border-radius: 6px;
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    transition: all 0.2s ease;
    white-space: nowrap;
}

.btn-card-reanalyze:hover:not(:disabled) {
    background: rgba(16, 185, 129, 0.15);
    border-color: rgba(16, 185, 129, 0.4);
    color: #6ee7b7;
    transform: translateY(-1px);
    box-shadow: 0 2px 8px rgba(16, 185, 129, 0.2);
}

.btn-card-reanalyze:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-card-reanalyze.btn-reanalyze-success {
    background: rgba(16, 185, 129, 0.35) !important;
    border-color: var(--accent-green) !important;
    color: #fff !important;
    box-shadow: 0 0 10px rgba(16, 185, 129, 0.4) !important;
}

/* ==========================================================================
   SUGESTÃO COMPARATIVA DE TAXONOMIA (DUAL-TAXONOMY: OPÇÃO A vs. OPÇÃO B)
   ========================================================================== */
.dual-taxonomy-box {
    background: linear-gradient(135deg, rgba(20, 24, 38, 0.95), rgba(15, 18, 30, 0.98));
